"""Misc helpers."""


def chunk_list(items, size):
    return [items[i:i + size] for i in range(0, len(items), size)]


def merge_dicts(*dicts):
    result = {}
    for d in dicts:
        result.update(d)
    return result


def flatten(nested):
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result


def unique_preserve_order(items):
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result


def safe_divide(numerator, denominator, default=0.0):
    if denominator == 0:
        return default
    return numerator / denominator

